new ResizeObserver(()=>{const w=view.clientWidth,h=view.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()}).observe(view);
function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera)}sample();animate();

function rationale(s){const p=s.params,descs={vertical:{title:'Vertical Flow｜成長を刻むリズム',structure:'細い縦方向の色帯を、長さと位置を変えて配置。連続長 '+p.run+' セルを生成の目安にし、全面を均一に埋めない構成です。',meaning:'上方向への動きから、成長・前進・将来への拡張を想起させます。物流の継続性を縦の流れに重ねた、今回の提案上の解釈です。',effect:'大きな壁面を細かな垂直要素に分節し、重さを和らげる狙いがあります。'},horizontal:{title:'Connected Horizon｜つながる物流の風景',structure:'横方向の色塊をずらして配置し、建物の長い輪郭に沿うリズムをつくります。連続長 '+p.run+' セルを生成の目安とします。',meaning:'拠点と拠点を結ぶ流れ、連携、物資の移動を表す提案です。各色塊をネットワークの接点として読み解きます。',effect:'低く長い建物のプロポーションを活かし、遠景での水平の連なりを強調する狙いがあります。'},scatter:{title:'Ordered Diversity｜秩序のある多様性',structure:'共通の格子の中に、色の異なるセルを分散配置。シード '+p.seed+' によって同じ配置を再現できます。',meaning:'多様な荷物・人・企業が一つの仕組みの中で協働する姿を、秩序と変化の共存として表す提案です。',effect:'単調な大壁面に視覚的な粒度を与え、見る距離によって印象が変わることを狙います。'}};const d=descs[p.style],active=s.cells.filter(v=>v>=0).length,dark=s.cells.filter(v=>v===2).length;return {...d,color:'ベース '+p.base+'、中間色 '+p.mid+'、アクセント '+p.dark+'。濃色の実セル比は '+(active?(dark/active*100).toFixed(1):0)+'%。色の名称・印象は参考であり、メーカー色票との照合が必要です。',caution:'設計者向けのコンセプト解釈です。Marqの公式ブランド理念を示すものではありません。手編集後は意図との整合を見直してください。'};}
function updateRationale(s){const r=s.aiNarrative||rationale(s);for(const k of ['title','structure','meaning','effect','color','caution'])$('rationale-'+k).textContent=r[k];}
$('exportRationale').onclick=()=>{if(!selected)return;const r=selected.aiNarrative||rationale(selected);download('# '+r.title+'\n\n## 图案构成 / 構成\n'+r.structure+'\n\n## 寓意 / 意味\n'+r.meaning+'\n\n## 视觉效果 / 視覚効果\n'+r.effect+'\n\n## 配色\n'+r.color+'\n\n'+r.caution+'\n','Marq-design-concept.md','text/markdown;charset=utf-8')};

function updateLighting(){const a=Number($('azimuth').value)*Math.PI/180,e=Number($('altitude').value)*Math.PI/180;sun.position.set(100*Math.sin(a)*Math.cos(e),100*Math.sin(e),100*Math.cos(a)*Math.cos(e));ambientLight.intensity=Number($('ambient').value);sun.intensity=Number($('sunpower').value);sun.castShadow=$('shadows').checked;for(const k of ['ambient','azimuth','altitude','sunpower'])$(k+'Val').textContent=$(k).value+(['azimuth','altitude'].includes(k)?'°':'');}
for(const k of ['ambient','azimuth','altitude','sunpower','shadows'])$(k).addEventListener('input',updateLighting);
$('environment').onchange=()=>{const choice=$('environment').value;const cfg={studio:[0xe9ede7,0xf3f7ff,0xfff5e3],day:[0xcddfeb,0xd8e9ff,0xffffff],sunset:[0xe3cdc0,0xf0dbd1,0xffc49b]}[choice];renderer.setClearColor(cfg[0]);scene.fog.color.setHex(cfg[0]);ambientLight.color.setHex(cfg[1]);sun.color.setHex(cfg[2]);updateLighting()};updateLighting();
$('realAi').onclick=async()=>{if(!selected){status('先に壁面を選択してください。');return}const token=$('aiToken').value;if(!token){status('自社サーバーのアクセストークンを入力してください。OpenAIキーではありません。');return}const btn=$('realAi');btn.disabled=true;const target=selected;status('AIがデザイン意向を解析しています…',true);try{const res=await fetch('./api/design',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({intent:$('intent').value,current:target.params}),signal:AbortSignal.timeout(65000)});if(!res.ok)throw Error(res.status===404||res.status===405?'このホスト版にはAIサーバーがありません。ソース一式の server.py を起動してください。':'AI API error '+res.status);const r=await res.json();if(!validParams(r.params))throw Error('AI応答のパラメータが不正です');if(target!==selected)throw Error('壁面が変更されたため適用を中止しました');remember();const resize=target.params.cols!==r.params.cols||target.params.rows!==r.params.rows;target.params=r.params;if(resize)target.cells=[];regenerate();if(r.narrative&&['title','structure','meaning','effect'].every(k=>typeof r.narrative[k]==='string'))target.aiNarrative={...rationale(target),...r.narrative};updateRationale(target);$('intentResult').textContent='生成AIから取得した案です。最終的な意図と施工条件をご確認ください。';status('AIの提案を反映しました。')}catch(e){status(e.message,true)}finally{btn.disabled=false}};

$('exportProposal').onclick=()=>{if(!selected){status('壁面を選択してください。');return}renderer.last=0;renderer.render(scene,camera);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const current={view:renderer.domElement.toDataURL('image/png'),narrative:selected.aiNarrative||rationale(selected),name:'現在の案'};const slides=[...saved,current];const html='<!doctype html><html lang="ja"><meta charset="utf-8"><title>Marq 外観デザイン提案</title><style>body{font-family:Arial,sans-serif;color:#243b30;margin:0}article{padding:35px 50px;max-width:1100px;margin:auto;page-break-after:always}h1{font-size:25px}img{width:100%;max-height:440px;object-fit:contain;background:#edf0e9}p{font-size:13px;line-height:1.8}.top{font-size:11px;letter-spacing:2px;color:#7b8d72}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.note{color:#899281;font-size:10px}@page{size:A4 landscape;margin:10mm}@media print{article{padding:0;max-width:none}img{max-height:90mm}h1{font-size:20px}p{font-size:10px}}</style>'+slides.map((x,i)=>'<article><div class="top">MARQ / FACADE DESIGN STUDY · '+new Date().toLocaleDateString('ja-JP')+'</div><h1>'+esc($('projectName').value||modelName)+' — '+esc(x.name)+'</h1><img src="'+x.view+'"><h2>'+esc(x.narrative.title)+'</h2><div class="grid"><div><b>構成と配色</b><p>'+esc(x.narrative.structure)+' '+esc(x.narrative.color)+'</p></div><div><b>意味と視覚的な狙い</b><p>'+esc(x.narrative.meaning)+' '+esc(x.narrative.effect)+'</p></div></div><p class="note">非公式コンセプト提案 / '+esc(x.narrative.caution)+'　表示画像は検討用。施工寸法・色票・実日照は未検証。'+(renderer.isSoftware?' 互換表示による簡易レンダリング。':'')+'</p></article>').join('')+'</html>';$('proposalFrame').srcdoc=html;if($('proposalDownload').href.startsWith('blob:'))URL.revokeObjectURL($('proposalDownload').href);$('proposalDownload').href=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));$('proposalDialog').showModal();status('提案書プレビューを作成しました。印刷またはHTML保存をご利用ください。')};

$('closeProposal').onclick=()=>$('proposalDialog').close();$('printProposal').onclick=()=>$('proposalFrame').contentWindow.print();

$('materialMode').onchange=()=>{applyMaterialMode(building,$('materialMode').value==='original');status($('materialMode').value==='original'?'元の材質を表示。数字・チェック柄も元モデル由来の貼図です。':'ニュートラル材質で配色確認。原本ファイルは変更しません。')};
$('colorCheck').onchange=()=>{surfaces.forEach(s=>{s.overlay.material.map=s.overlay.material.map; s.overlay.material.dispose();s.overlay.material=$('colorCheck').checked?new THREE.MeshBasicMaterial({map:s.overlay.material.map,alphaTest:.5,transparent:false,depthTest:true,depthWrite:true,polygonOffset:true,polygonOffsetFactor:-2,polygonOffsetUnits:-2,side:THREE.DoubleSide}):patternMaterial(s.overlay.material.map)});status($('colorCheck').checked?'色見本モード：光照の影響なし。陰影確認はOFFにしてください。':'陰影付き材質に戻しました。')};
